// The body of every story: its intro, what it cannot say (limits) and its scenes, by slug. Loaded only by a story's
// page (app.js); the first page and the cards need only what text.js has. `STORIES` is every story whole: its card
// from text.js with its body here.
import { STORIES as CARDS } from "./text.js";

// Stories. Each opens on a question people argue about, turns on something the counting found, and ends on what
// it cannot tell. A scene names a figure (see SCENES in app.js) shown on a stage; its steps turn one after another beside it, each
// naming the moment to show (`at`), what to bring forward (`focus`; "*" is the row of all pages), a moment
// inside a plate (`mark`) and the caption's heading (`head`). `check` lists the words to look up. A count from the text
// may carry what was read by hand in it (`read`: the places, data/pages/<name>-read.json, in rows by one reading (`by`,
// `groups`) and marked by another (`fill`, `fills`)); the step whose `at` is its name shows it, one mark per place.
const K = "id-web-news-kompas";
const s = (at, id, en, focus, mark, head) => ({ at, id, en, focus, mark, head });
